"use client";
/* eslint-disable @next/next/no-img-element -- Local optimized demo assets; next/image is not part of this vinext runtime. */

import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent } from "react";
import { ApiError, fetchJson, formatDate, formatMoney, normalizeProduct, statusLabel, unwrapList, type Product } from "../lib/frontend";
import Link from "next/link";
import { BundleAdmin, ProfitDashboard } from "./revenue-panels";

const ADMIN_KEY = "mleko-i-mleko-admin-secret";
type Access = { authenticated: boolean; configured: boolean; mode: "local" | "key" };
type Connection = "checking" | "required" | "ready" | "unconfigured" | "error";
type Row = Record<string, unknown>;
type Tab = "pregled" | "zarada" | "porudzbine" | "proizvodi" | "paketi" | "kupci" | "pretplate" | "dostave" | "popusti" | "sadrzaj" | "podesavanja";
type AdminData = { dashboard: Row; products: Product[]; bundles: Row[]; orders: Row[]; customers: Row[]; subscriptions: Row[]; deliveries: Row[]; delivery: Row; deliveryPreparation: Row[]; deliveryCanGenerate: boolean; promos: Row[]; settings: Row; integrations: Row };
const emptyData: AdminData = { dashboard: {}, products: [], bundles: [], orders: [], customers: [], subscriptions: [], deliveries: [], delivery: {}, deliveryPreparation: [], deliveryCanGenerate: false, promos: [], settings: {}, integrations: {} };

function row(value: unknown): Row { return value && typeof value === "object" ? value as Row : {}; }
function string(value: unknown, fallback = "-") { return typeof value === "string" && value ? value : fallback; }
function number(value: unknown, fallback = 0) { const parsed = Number(value); return Number.isFinite(parsed) ? parsed : fallback; }
function bool(value: unknown, fallback = false) { return value === true || value === 1 || value === "1" ? true : value === false || value === 0 || value === "0" ? false : fallback; }
function idOf(value: Row) { return string(value.id ?? value.customerId ?? value.customer_id ?? value.subscriptionId ?? value.subscription_id ?? value.orderId ?? value.order_id); }
function extractObject(payload: unknown, keys: string[]): Row { const wrapper = row(payload); for (const key of keys) if (wrapper[key] && typeof wrapper[key] === "object" && !Array.isArray(wrapper[key])) return row(wrapper[key]); return wrapper.data && typeof wrapper.data === "object" && !Array.isArray(wrapper.data) ? row(wrapper.data) : wrapper; }
function businessDate() { return new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Belgrade", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date()); }

const nav: Array<{ id: Tab; label: string; icon: string }> = [
  { id: "pregled", label: "Pregled", icon: "⌂" },
  { id: "zarada", label: "Zarada", icon: "↗" },
  { id: "porudzbine", label: "Porudžbine", icon: "▤" },
  { id: "proizvodi", label: "Proizvodi", icon: "□" },
  { id: "paketi", label: "Paketi", icon: "▦" },
  { id: "kupci", label: "Kupci", icon: "◎" },
  { id: "pretplate", label: "Pretplate", icon: "↻" },
  { id: "dostave", label: "Dostave", icon: "→" },
  { id: "popusti", label: "Popusti", icon: "%" },
  { id: "sadrzaj", label: "Sadržaj sajta", icon: "✎" },
  { id: "podesavanja", label: "Podešavanja", icon: "⚙" },
];

export function AdminDashboard() {
  const [secret, setSecret] = useState("");
  const [activeSecret, setActiveSecret] = useState("");
  const [connection, setConnection] = useState<Connection>("checking");
  const [accessMode, setAccessMode] = useState<Access["mode"]>("key");
  const loadVersion = useRef(0);
  const [activeTab, setActiveTab] = useState<Tab>("pregled");
  const [data, setData] = useState<AdminData>(emptyData);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [deliveryDate, setDeliveryDate] = useState(businessDate);
  const [billingMonth, setBillingMonth] = useState(() => businessDate().slice(0, 7));
  const [editingProduct, setEditingProduct] = useState<Product | null | undefined>(undefined);

  const checkAccess = useCallback(async (key = "", signal?: AbortSignal) => {
    setConnection("checking"); setError("");
    try {
      const access = await fetchJson<Access>("/api/admin/access", { signal, headers: key ? { "x-admin-secret": key } : {} });
      if (signal?.aborted) return;
      setAccessMode(access.mode);
      setActiveSecret(access.authenticated && access.mode === "key" ? key : "");
      setConnection(access.authenticated ? "ready" : access.configured ? "required" : "unconfigured");
      if (access.authenticated) setSecret("");
    } catch (requestError) {
      if (signal?.aborted) return;
      setActiveSecret("");
      setConnection(requestError instanceof ApiError && requestError.code === "ADMIN_FORBIDDEN" ? "required" : requestError instanceof ApiError && requestError.code === "ADMIN_NOT_CONFIGURED" ? "unconfigured" : "error");
      setError(requestError instanceof Error ? requestError.message : "Provera pristupa nije uspela.");
    }
  }, []);
  useEffect(() => {
    const controller = new AbortController();
    // Remove the old permanent browser credential. Credentials now live only in
    // memory for this page; typing a key never starts data requests.
    try { window.localStorage.removeItem(ADMIN_KEY); } catch { /* Storage may be disabled. */ }
    queueMicrotask(() => { if (!controller.signal.aborted) void checkAccess("", controller.signal); });
    return () => { controller.abort(); loadVersion.current += 1; };
  }, [checkAccess]);
  const adminFetch = useCallback(<T,>(url: string, init?: RequestInit) => fetchJson<T>(url, { ...init, headers: { ...(activeSecret ? { "x-admin-secret": activeSecret } : {}), ...init?.headers } }), [activeSecret]);

  const loadAdmin = useCallback(async () => {
    if (connection !== "ready") return;
    const version = ++loadVersion.current;
    setLoading(true); setError("");
    const endpoints = [
      ["dashboard", "/api/admin/dashboard"], ["products", "/api/admin/products"], ["orders", "/api/admin/orders"],
      ["customers", "/api/admin/customers"], ["subscriptions", "/api/admin/subscriptions"],
      ["deliveries", `/api/admin/deliveries?date=${encodeURIComponent(deliveryDate)}`], ["promos", "/api/admin/promos"], ["bundles", "/api/admin/bundles"], ["settings", "/api/admin/settings"], ["integrations", "/api/admin/integrations"],
    ] as const;
    const results = await Promise.allSettled(endpoints.map(([, endpoint]) => adminFetch<unknown>(endpoint)));
    if (version !== loadVersion.current) return;
    const accessFailure = results.find((result) => result.status === "rejected" && result.reason instanceof ApiError && ["ADMIN_FORBIDDEN", "ADMIN_NOT_CONFIGURED"].includes(result.reason.code ?? ""));
    if (accessFailure?.status === "rejected") {
      setData(emptyData); setActiveSecret(""); setLoading(false);
      setConnection(accessFailure.reason.code === "ADMIN_NOT_CONFIGURED" ? "unconfigured" : "required");
      setError(accessFailure.reason.message); return;
    }
    const next: AdminData = { ...emptyData }; const failed: string[] = [];
    results.forEach((result, index) => {
      const name = endpoints[index][0]; if (result.status === "rejected") { failed.push(name); return; }
      if (name === "products") next.products = unwrapList(result.value, ["products", "items"]).map(normalizeProduct);
      else if (name === "dashboard") next.dashboard = extractObject(result.value, ["dashboard", "stats"]);
      else if (name === "settings") next.settings = extractObject(result.value, ["settings"]);
      else if (name === "integrations") next.integrations = row(result.value);
      else if (name === "deliveries") {
        next.deliveries = unwrapList(result.value, ["orders", "deliveries", "items"]).map(row);
        next.delivery = extractObject(result.value, ["delivery"]);
        next.deliveryPreparation = unwrapList(result.value, ["preparation"]).map(row);
        next.deliveryCanGenerate = row(result.value).canGenerate === true;
      }
      else next[name] = unwrapList(result.value, [name, "items"]).map(row) as never;
    });
    const labels: Record<string, string> = { dashboard: "pregled", products: "proizvodi", orders: "porudžbine", customers: "kupci", subscriptions: "pretplate", deliveries: "dostave", promos: "popusti", bundles: "paketi", settings: "podešavanja", integrations: "integracije" };
    const databaseFailure = results.some((result) => result.status === "rejected" && result.reason instanceof ApiError && result.reason.code === "DATABASE_NOT_READY");
    setData(next);
    if (failed.length) setError(databaseFailure ? "Baza podataka nije spremna. Primenite migracije i osvežite stranicu." : `Nije uspelo učitavanje: ${failed.map((name) => labels[name]).join(", ")}. Pokušajte ponovo pomoću dugmeta Osveži.`);
    setLoading(false);
  }, [adminFetch, connection, deliveryDate]);
  useEffect(() => {
    let cancelled = false;
    queueMicrotask(() => { if (!cancelled) void loadAdmin(); });
    return () => { cancelled = true; loadVersion.current += 1; };
  }, [loadAdmin]);

  function start(message = "") { setBusy(true); setError(""); setNotice(message); }
  function fail(requestError: unknown, fallback: string) { setError(requestError instanceof Error ? requestError.message : fallback); }
  async function refresh(message: string) { setNotice(message); await loadAdmin(); }
  function saveSecret(event: FormEvent<HTMLFormElement>) { event.preventDefault(); void checkAccess(secret); }
  function disconnect() { loadVersion.current += 1; setActiveSecret(""); setSecret(""); setData(emptyData); setNotice(""); setError(""); setConnection("required"); }

  async function saveProduct(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = event.currentTarget; const values = new FormData(form); start();
    const payload = {
      name: values.get("name"), slug: values.get("slug"), category: values.get("category"), unitLabel: values.get("unitLabel"),
      priceMinor: Math.round(Number(values.get("priceRsd")) * 100), subscriptionPriceMinor: Math.round(Number(values.get("subscriptionPriceRsd") || values.get("priceRsd")) * 100),
      costMinor: Math.round(Number(values.get("costRsd") || 0) * 100), packagingCostMinor: Math.round(Number(values.get("packagingCostRsd") || 0) * 100),
      compareAtPriceMinor: values.get("compareAtPriceRsd") ? Math.round(Number(values.get("compareAtPriceRsd")) * 100) : null,
      shortDescription: values.get("shortDescription"), description: values.get("description"), imageUrl: values.get("imageUrl"), imageAlt: values.get("imageAlt"),
      badge: values.get("badge"), origin: values.get("origin"), sortOrder: Number(values.get("sortOrder") || 0),
      seoTitle: values.get("seoTitle"), seoDescription: values.get("seoDescription"),
      badiSku: values.get("badiSku") ? Number(values.get("badiSku")) : null,
      isFeatured: values.get("isFeatured") === "on", allowSubscription: values.get("allowSubscription") === "on", isDemo: values.get("isDemo") === "on", isActive: values.get("isActive") === "on",
    };
    try {
      const url = editingProduct ? `/api/admin/products/${encodeURIComponent(editingProduct.id)}` : "/api/admin/products";
      await adminFetch(url, { method: editingProduct ? "PATCH" : "POST", body: JSON.stringify(payload) });
      setEditingProduct(undefined); await refresh(editingProduct ? "Proizvod je sačuvan." : "Proizvod je dodat.");
    } catch (requestError) { fail(requestError, "Proizvod nije sačuvan."); } finally { setBusy(false); }
  }

  async function toggleProduct(product: Product) { start(); try { await adminFetch(`/api/admin/products/${encodeURIComponent(product.id)}`, { method: "PATCH", body: JSON.stringify({ isActive: !product.available }) }); await refresh(product.available ? "Proizvod je sakriven." : "Proizvod je objavljen."); } catch (e) { fail(e, "Izmena nije sačuvana."); } finally { setBusy(false); } }
  async function deleteProduct(product: Product) { if (!window.confirm(`Obrisati „${product.name}“? Ako ima porudžbine, biće bezbedno arhiviran.`)) return; start(); try { const result = await adminFetch<{ archived?: boolean }>(`/api/admin/products/${encodeURIComponent(product.id)}`, { method: "DELETE" }); await refresh(result.archived ? "Proizvod ima istoriju pa je arhiviran." : "Demo proizvod je obrisan."); } catch (e) { fail(e, "Proizvod nije obrisan."); } finally { setBusy(false); } }

  async function saveSettings(event: FormEvent<HTMLFormElement>, kind: "content" | "operations") {
    event.preventDefault(); const values = new FormData(event.currentTarget); start();
    const payload = kind === "content" ? {
      storeName: values.get("storeName"), announcementEnabled: values.get("announcementEnabled") === "on", announcementText: values.get("announcementText"), announcementLinkLabel: values.get("announcementLinkLabel"), announcementUrl: values.get("announcementUrl"),
      heroEyebrow: values.get("heroEyebrow"), heroTitle: values.get("heroTitle"), heroSubtitle: values.get("heroSubtitle"), heroPrimaryLabel: values.get("heroPrimaryLabel"), heroPrimaryUrl: values.get("heroPrimaryUrl"), heroSecondaryLabel: values.get("heroSecondaryLabel"), heroSecondaryUrl: values.get("heroSecondaryUrl"),
      guaranteeTitle: values.get("guaranteeTitle"), guaranteeText: values.get("guaranteeText"), trustItemOne: values.get("trustItemOne"), trustItemTwo: values.get("trustItemTwo"), trustItemThree: values.get("trustItemThree"), storeDemoMode: values.get("storeDemoMode") === "on",
    } : {
      cutoffHours: Number(values.get("cutoffHours")), deliveryWeekday: Number(values.get("deliveryWeekday")), deliveryLocalTime: values.get("deliveryLocalTime"), serviceAreaTitle: values.get("serviceAreaTitle"), serviceAreaNote: values.get("serviceAreaNote"), servicePostalCodes: String(values.get("servicePostalCodes") ?? "").split(",").map((item) => item.trim()).filter(Boolean), deliveryFeeMinor: Math.round(Number(values.get("deliveryFeeRsd") || 0) * 100), freeDeliveryThresholdMinor: Math.round(Number(values.get("freeDeliveryThresholdRsd") || 0) * 100), routeCapacity: Number(values.get("routeCapacity") || 0), estimatedDeliveryCostMinor: Math.round(Number(values.get("estimatedDeliveryCostRsd") || 0) * 100), paymentFeeBps: Math.round(Number(values.get("paymentFeePercent") || 0) * 100),
    };
    try { await adminFetch("/api/admin/settings", { method: "PATCH", body: JSON.stringify(payload) }); await refresh("Podešavanja su sačuvana i odmah su vidljiva na sajtu."); } catch (e) { fail(e, "Podešavanja nisu sačuvana."); } finally { setBusy(false); }
  }

  async function createPromo(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const values = new FormData(form); start(); try { await adminFetch("/api/admin/promos", { method: "POST", body: JSON.stringify({ code: values.get("code"), description: values.get("description"), discountType: values.get("discountType"), discountValue: values.get("discountType") === "fixed" ? Math.round(Number(values.get("discountValue")) * 100) : Number(values.get("discountValue")), minimumOrderMinor: Math.round(Number(values.get("minimumOrderRsd") || 0) * 100), usageLimit: values.get("usageLimit") || null, isActive: true }) }); form.reset(); await refresh("Promo kod je dodat."); } catch (e) { fail(e, "Promo kod nije dodat."); } finally { setBusy(false); } }
  async function togglePromo(promo: Row) { start(); try { await adminFetch(`/api/admin/promos/${encodeURIComponent(idOf(promo))}`, { method: "PATCH", body: JSON.stringify({ isActive: !bool(promo.is_active) }) }); await refresh("Status promo koda je promenjen."); } catch (e) { fail(e, "Promo kod nije izmenjen."); } finally { setBusy(false); } }
  async function deletePromo(promo: Row) { if (!window.confirm(`Obrisati kod ${string(promo.code)}?`)) return; start(); try { await adminFetch(`/api/admin/promos/${encodeURIComponent(idOf(promo))}`, { method: "DELETE" }); await refresh("Promo kod je obrisan."); } catch (e) { fail(e, "Promo kod nije obrisan."); } finally { setBusy(false); } }
  async function saveBundle(id: string | null, payload: Row) { start(); try { await adminFetch(id ? `/api/admin/bundles/${encodeURIComponent(id)}` : "/api/admin/bundles", { method: id ? "PATCH" : "POST", body: JSON.stringify(payload) }); await refresh(id ? "Paket je sačuvan." : "Paket je dodat."); } catch (e) { fail(e, "Paket nije sačuvan."); throw e; } finally { setBusy(false); } }
  async function deleteBundle(id: string) { if (!window.confirm("Obrisati ovaj paket?")) return; start(); try { await adminFetch(`/api/admin/bundles/${encodeURIComponent(id)}`, { method: "DELETE" }); await refresh("Paket je obrisan."); } catch (e) { fail(e, "Paket nije obrisan."); } finally { setBusy(false); } }
  async function saveOrder(id: string, paymentStatus: string, fulfillmentStatus: string) { start(); try { await adminFetch("/api/admin/orders", { method: "PATCH", body: JSON.stringify({ id, paymentStatus, fulfillmentStatus }) }); await refresh("Porudžbina je ažurirana."); } catch (e) { fail(e, "Porudžbina nije ažurirana."); } finally { setBusy(false); } }

  async function runDeliveryAction(action: "generate" | "lock") { start(); try { await adminFetch("/api/admin/deliveries", { method: "POST", headers: { "Idempotency-Key": window.crypto.randomUUID() }, body: JSON.stringify({ action, date: deliveryDate }) }); await refresh(action === "generate" ? "Lista dostave je generisana." : "Dostava je zaključana."); } catch (e) { fail(e, "Operacija dostave nije uspela."); } finally { setBusy(false); } }
  async function queueReminders() { start(); try { const result = await adminFetch<{ queued?: number }>("/api/admin/integrations", { method: "POST", body: JSON.stringify({ action: "delivery_reminders", date: deliveryDate }) }); await adminFetch("/api/admin/integrations", { method: "POST", body: JSON.stringify({ action: "process", limit: 100 }) }); await refresh(`Zakazano je ${number(result.queued)} podsetnika za dostavu.`); } catch (e) { fail(e, "Podsetnici nisu zakazani."); } finally { setBusy(false); } }
  async function runBilling() { start(); try { const result = await adminFetch<{ processed?: number }>("/api/jobs/billing", { method: "POST", headers: { "Idempotency-Key": window.crypto.randomUUID() }, body: JSON.stringify({ month: billingMonth }) }); await refresh(`Mesečni obračun je završen: ${number(result.processed)} pretplata.`); } catch (e) { fail(e, "Mesečni obračun nije uspeo."); } finally { setBusy(false); } }
  async function runIntegrationAction(action: "process" | "retry_failed") { start(); try { const result = await adminFetch<Row>("/api/admin/integrations", { method: "POST", body: JSON.stringify({ action, limit: 100 }) }); await refresh(action === "process" ? `Obrađeno događaja: ${number(result.attempted)}.` : `Vraćeno u red: ${number(result.requeued)}.`); } catch (e) { fail(e, "Integracioni red nije obrađen."); } finally { setBusy(false); } }
  async function downloadDeliveryExport(format: "csv" | "xlsx") { start(); try { const response = await fetch(`/api/admin/deliveries/export?date=${encodeURIComponent(deliveryDate)}&format=${format}`, { headers: activeSecret ? { "x-admin-secret": activeSecret } : {} }); if (!response.ok) throw new Error(`${format.toUpperCase()} nije generisan.`); const url = URL.createObjectURL(await response.blob()); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `mleko-dostave-${deliveryDate}.${format}`; anchor.click(); URL.revokeObjectURL(url); setNotice(format === "csv" ? "CSV za Spoke je preuzet." : "Excel sa dostavama i zbirnom pripremom je preuzet."); } catch (e) { fail(e, "Izvoz nije generisan."); } finally { setBusy(false); } }

  const preparation = useMemo(() => unwrapList(data.dashboard, ["preparation"]).map(row), [data.dashboard]);
  const counts = row(data.dashboard.counts); const revenue = row(data.dashboard.revenue);
  const s = data.settings;

  if (connection !== "ready") return (
    <div className="admin-access">
      <section className="admin-access-card" aria-labelledby="admin-access-title">
        <Link className="admin-brand" href="/"><img src="/images/mleko-i-mleko-logo.png" alt="" width="80" height="80" /><strong>Mleko Admin</strong></Link>
        <h1 id="admin-access-title">{connection === "checking" ? "Proveravamo pristup…" : connection === "unconfigured" ? "Pristup još nije podešen" : "Prijava u administraciju"}</h1>
        {connection === "checking" ? <p role="status">Sačekajte trenutak.</p> : null}
        {connection === "unconfigured" ? <p>Postavite admin ključ u podešavanjima servera i ponovo pokrenite aplikaciju.</p> : null}
        {error ? <p className="notice error" role="alert">{error}</p> : null}
        {connection === "required" ? <form className="admin-form" onSubmit={saveSecret}><label className="field"><span>Admin ključ</span><input type="password" autoComplete="current-password" value={secret} onChange={(event) => setSecret(event.target.value)} required /></label><button className="button" type="submit">Prijavi se</button></form> : null}
        {connection === "error" || connection === "unconfigured" ? <button className="button secondary" type="button" onClick={() => void checkAccess()}>Pokušaj ponovo</button> : null}
        <Link className="text-link" href="/">Nazad u prodavnicu</Link>
      </section>
    </div>
  );

  return (
    <div className="admin-app">
      <aside className="admin-sidebar">
        <a className="admin-brand" href="/admin"><img src="/images/mleko-i-mleko-logo.png" alt="" width="4167" height="4167" /><strong>Mleko Admin</strong></a>
        <nav aria-label="Administracija">{nav.map((item) => <button key={item.id} type="button" className={activeTab === item.id ? "active" : ""} onClick={() => { setActiveTab(item.id); setEditingProduct(undefined); }}><span aria-hidden="true">{item.icon}</span>{item.label}</button>)}</nav>
        <a className="admin-store-link" href="/" target="_blank" rel="noreferrer">Otvori prodavnicu ↗</a>
      </aside>
      <section className="admin-main">
        <header className="admin-topbar"><div><p className="eyebrow">{accessMode === "local" ? "Lokalna administracija" : "Administracija"}</p><h1>{nav.find((item) => item.id === activeTab)?.label}</h1></div><div className="admin-top-actions"><span className="status-dot" role="status">{loading ? "Učitavanje…" : error ? "Potrebna provera" : "● Povezano"}</span><button className="button secondary small" type="button" disabled={loading} onClick={loadAdmin}>Osveži</button>{accessMode === "key" ? <button className="text-button" type="button" onClick={disconnect}>Odjavi se</button> : null}</div></header>
        {notice ? <p className="notice success" role="status">{notice}</p> : null}{error ? <p className="notice error" role="alert">{error}</p> : null}
        {loading ? <p className="loading-state">Učitavamo administraciju…</p> : <section className="admin-content">
          {activeTab === "pregled" ? <><div className="dashboard-grid"><Stat label="Prihod" value={formatMoney(number(revenue.paid_revenue_minor) / 100)} /><Stat label="Porudžbine" value={number(counts.orders)} /><Stat label="Aktivne pretplate" value={number(counts.active_subscriptions)} /><Stat label="Kupci" value={number(counts.customers)} /></div><div className="admin-grid-2"><section className="admin-panel"><div className="panel-heading"><h2>Brze akcije</h2></div><div className="quick-actions"><button type="button" onClick={() => { setActiveTab("proizvodi"); setEditingProduct(null); }}>＋ Dodaj proizvod</button><button type="button" onClick={() => setActiveTab("porudzbine")}>▤ Obradi porudžbine</button><button type="button" onClick={() => setActiveTab("sadrzaj")}>✎ Izmeni početnu</button><button type="button" onClick={() => setActiveTab("dostave")}>→ Pripremi dostavu</button></div></section><section className="admin-panel"><div className="panel-heading"><h2>Sledeće za pripremu</h2></div>{preparation.length ? <ul className="list-clean">{preparation.slice(0, 8).map((item, index) => <li className="summary-row" key={index}><span>{string(item.product_name)} <small>{string(item.unit_label, "")}</small></span><strong>{number(item.total_quantity)}</strong></li>)}</ul> : <p className="admin-empty">Nema zaključanih količina za pripremu.</p>}</section></div></> : null}
          {activeTab === "zarada" ? <ProfitDashboard dashboard={data.dashboard} /> : null}

          {activeTab === "proizvodi" ? <section className="admin-panel"><div className="panel-heading"><div><h2>Svi proizvodi</h2><p>{data.products.length} proizvoda · demo proizvodi su označeni</p></div><button className="button small" type="button" onClick={() => setEditingProduct(null)}>＋ Dodaj proizvod</button></div>{editingProduct !== undefined ? <ProductForm product={editingProduct} busy={busy} onSubmit={saveProduct} onCancel={() => setEditingProduct(undefined)} /> : null}<div className="product-admin-list">{data.products.map((product) => <article key={product.id}><div className="admin-product-image">{product.imageUrl ? <img src={product.imageUrl} alt="" width="1080" height="1080" loading="lazy" /> : <span>□</span>}</div><div><strong>{product.name}</strong><p>{product.category} · {product.unit}{product.isDemo ? " · DEMO" : ""}</p></div><div><strong>{formatMoney(product.priceRsd)}</strong><p>{product.allowSubscription ? `Redovno ${formatMoney(product.subscriptionPriceRsd)}` : "Samo jednokratno"}</p></div><span className={`status-pill ${product.available ? "active" : ""}`}>{product.available ? "Objavljen" : "Sakriven"}</span><div className="row-actions"><button type="button" onClick={() => setEditingProduct(product)}>Izmeni</button><button type="button" onClick={() => void toggleProduct(product)}>{product.available ? "Sakrij" : "Objavi"}</button><button className="danger-text" type="button" onClick={() => void deleteProduct(product)}>Obriši</button></div></article>)}</div></section> : null}
          {activeTab === "paketi" ? <BundleAdmin products={data.products.filter((product) => product.available)} bundles={data.bundles} busy={busy} onSave={saveBundle} onDelete={deleteBundle} /> : null}

          {activeTab === "porudzbine" ? <section className="admin-panel"><div className="panel-heading"><div><h2>Porudžbine</h2><p>Promena statusa se odmah upisuje u operativni sistem.</p></div></div>{data.orders.length ? <div className="table-wrap"><table><thead><tr><th>Porudžbina</th><th>Kupac</th><th>Dostava</th><th>Ukupno</th><th>Naplata</th><th>Račun</th><th>Ispunjenje</th><th></th></tr></thead><tbody>{data.orders.map((order) => <OrderRow key={idOf(order)} order={order} busy={busy} onSave={saveOrder} />)}</tbody></table></div> : <p className="admin-empty">Još nema porudžbina.</p>}</section> : null}

          {activeTab === "kupci" ? <DataTable headers={["Kupac", "Kontakt", "Adresa", "Porudžbine", "LTV"]} empty="Još nema kupaca.">{data.customers.map((customer) => <tr key={idOf(customer)}><td><strong>{string(customer.full_name)}</strong></td><td>{string(customer.email)}<br />{string(customer.phone)}</td><td>{[customer.address_line_1, customer.postal_code, customer.city].filter(Boolean).join(", ")}</td><td>{number(customer.order_count)}</td><td>{formatMoney(number(customer.lifetime_value_minor) / 100)}</td></tr>)}</DataTable> : null}
          {activeTab === "pretplate" ? <DataTable headers={["Kupac", "Status", "Plaćanje", "Stavke", "Sledeća dostava"]} empty="Još nema pretplata.">{data.subscriptions.map((subscription) => <tr key={idOf(subscription)}><td><strong>{string(subscription.full_name)}</strong><br />{string(subscription.email)}</td><td><span className="status-pill active">{statusLabel(string(subscription.status))}</span></td><td>{string(subscription.payment_method)}</td><td>{number(subscription.item_count)}</td><td>{formatDate(string(subscription.next_delivery_date, ""))}</td></tr>)}</DataTable> : null}

          {activeTab === "dostave" ? <div className="admin-stack"><section className="admin-panel"><div className="panel-heading"><div><h2>Dostave za petak</h2><p>Generišite, zaključajte i izvezite istu operativnu projekciju za izabrani dan.</p></div><span className={`status-pill ${string(data.delivery.status) === "locked" ? "active" : ""}`}>{string(data.delivery.status, "nije generisana")}</span></div>{data.deliveryCanGenerate ? <p className="notice" role="status">Za ovaj datum još nema liste. Izaberite „Generiši” da napravite praznu ili popunjenu projekciju.</p> : null}<div className="inline-controls"><label className="field"><span>Datum</span><input type="date" value={deliveryDate} onChange={(event) => setDeliveryDate(event.target.value)} /></label><button className="button secondary small" type="button" onClick={loadAdmin}>Učitaj</button><button className="button secondary small" type="button" disabled={busy} onClick={() => void runDeliveryAction("generate")}>{data.deliveryCanGenerate ? "Generiši" : "Osveži"}</button><button className="button danger small" type="button" disabled={busy || data.deliveryCanGenerate} onClick={() => window.confirm("Zaključati dostavu? Posle zaključavanja izmene više ne ulaze u listu.") && void runDeliveryAction("lock")}>Zaključaj</button><button className="button small" type="button" disabled={busy || data.deliveryCanGenerate} onClick={() => void downloadDeliveryExport("csv")}>CSV za Spoke</button><button className="button secondary small" type="button" disabled={busy || data.deliveryCanGenerate} onClick={() => void downloadDeliveryExport("xlsx")}>Excel + priprema</button><button className="button secondary small" type="button" disabled={busy || data.deliveryCanGenerate} onClick={() => void queueReminders()}>Pošalji podsetnike</button></div></section><div className="admin-grid-2"><section className="admin-panel"><div className="panel-heading"><div><h2>Zbir za pripremu</h2><p>{formatDate(deliveryDate)} · {data.deliveries.length} adresa</p></div></div>{data.deliveryPreparation.length ? <ul className="list-clean">{data.deliveryPreparation.map((item, index) => <li className="summary-row" key={`${string(item.product_id)}-${index}`}><span>{string(item.product_name)} <small>{string(item.unit_label, "")}</small></span><strong>{number(item.total_quantity)}</strong></li>)}</ul> : <p className="admin-empty">Nema robe za pripremu za izabrani datum.</p>}</section><section className="admin-panel"><div className="panel-heading"><div><h2>Kontrola liste</h2><p>Otvorena lista se ponovo obračunava iz aktuelnih porudžbina i izmena pretplata.</p></div></div><ul className="list-clean"><li className="summary-row"><span>Porudžbina za dostavu</span><strong>{data.deliveries.length}</strong></li><li className="summary-row"><span>Različitih proizvoda</span><strong>{data.deliveryPreparation.length}</strong></li><li className="summary-row"><span>Rok za izmenu</span><strong>{data.deliveryCanGenerate ? "—" : formatDate(string(data.delivery.cutoff_at, ""))}</strong></li></ul></section></div><DataTable headers={["ID", "Kupac", "Adresa", "Kontakt", "Proizvodi", "Napomena"]} empty="Nema dostava za izabrani datum.">{data.deliveries.map((delivery) => { const snapshot = row(delivery.customer_snapshot ?? delivery.customerSnapshot); return <tr key={idOf(delivery)}><td>{idOf(delivery)}</td><td>{string(delivery.customer_name ?? snapshot.fullName)}</td><td>{[snapshot.addressLine1, snapshot.addressLine2, snapshot.postalCode, snapshot.city].filter(Boolean).join(", ")}</td><td>{string(delivery.phone ?? snapshot.phone)}<br /><small>{string(delivery.email ?? snapshot.email)}</small></td><td>{unwrapList(delivery, ["items"]).map(row).map((item) => `${number(item.quantity)}× ${string(item.product_name ?? item.name)} ${string(item.unit_label ?? item.unit, "")}`).join(", ") || "-"}</td><td>{string(delivery.note)}</td></tr>; })}</DataTable></div> : null}

          {activeTab === "popusti" ? <div className="admin-grid-2"><form className="admin-panel admin-form" onSubmit={createPromo}><div className="panel-heading"><div><h2>Novi promo kod</h2><p>Popust se proverava u korpi i checkout-u.</p></div></div><label className="field"><span>Kod</span><input name="code" placeholder="DOBRODOSLI10" pattern="[A-Za-z0-9_-]+" required /></label><label className="field"><span>Interni opis</span><input name="description" /></label><div className="form-grid"><label className="field"><span>Vrsta</span><select name="discountType"><option value="percent">Procenat</option><option value="fixed">Fiksni RSD</option></select></label><label className="field"><span>Vrednost</span><input name="discountValue" type="number" min="1" required /></label><label className="field"><span>Minimalna porudžbina (RSD)</span><input name="minimumOrderRsd" type="number" min="0" defaultValue="0" /></label><label className="field"><span>Limit korišćenja</span><input name="usageLimit" type="number" min="1" /></label></div><button className="button" type="submit" disabled={busy}>Dodaj kod</button></form><section className="admin-panel"><div className="panel-heading"><h2>Aktivni kodovi</h2></div><div className="promo-list">{data.promos.map((promo) => <article key={idOf(promo)}><div><code>{string(promo.code)}</code><p>{string(promo.description, "Bez opisa")}</p></div><strong>{string(promo.discount_type) === "percent" ? `${number(promo.discount_value)}%` : formatMoney(number(promo.discount_value) / 100)}</strong><span>{number(promo.times_used)} korišćenja</span><div className="row-actions"><button type="button" onClick={() => void togglePromo(promo)}>{bool(promo.is_active) ? "Pauziraj" : "Aktiviraj"}</button><button className="danger-text" type="button" onClick={() => void deletePromo(promo)}>Obriši</button></div></article>)}{!data.promos.length ? <p className="admin-empty">Nema promo kodova.</p> : null}</div></section></div> : null}

          {activeTab === "sadrzaj" ? <form className="admin-panel admin-form wide-form" key={JSON.stringify(s)} onSubmit={(event) => void saveSettings(event, "content")}><div className="panel-heading"><div><h2>Početna strana i announcement bar</h2><p>Promene su odmah vidljive na sajtu.</p></div><button className="button small" type="submit" disabled={busy}>Sačuvaj sve</button></div><FormSection title="Brend i režim"><label className="field"><span>Naziv prodavnice</span><input name="storeName" defaultValue={string(s.storeName, "Mleko i Mleko")} required /></label><Check name="storeDemoMode" label="Prikaži DEMO oznake" checked={bool(s.storeDemoMode, true)} /></FormSection><FormSection title="Announcement bar" description="Traka iznad glavne navigacije; tekst i link su potpuno izmenjivi."><Check name="announcementEnabled" label="Prikaži announcement bar" checked={bool(s.announcementEnabled)} /><div className="form-grid"><label className="field"><span>Tekst</span><input name="announcementText" defaultValue={string(s.announcementText, "")} required /></label><label className="field"><span>Tekst linka</span><input name="announcementLinkLabel" defaultValue={string(s.announcementLinkLabel, "Saznaj više")} required /></label><label className="field"><span>Link</span><input name="announcementUrl" defaultValue={string(s.announcementUrl, "/prodavnica")} required /></label></div></FormSection><FormSection title="Glavni hero"><label className="field"><span>Nadnaslov</span><input name="heroEyebrow" defaultValue={string(s.heroEyebrow, "")} required /></label><label className="field"><span>Naslov</span><input name="heroTitle" defaultValue={string(s.heroTitle, "")} required /></label><label className="field"><span>Podnaslov</span><textarea name="heroSubtitle" defaultValue={string(s.heroSubtitle, "")} required /></label><div className="form-grid"><label className="field"><span>Glavno dugme</span><input name="heroPrimaryLabel" defaultValue={string(s.heroPrimaryLabel, "")} required /></label><label className="field"><span>Glavni link</span><input name="heroPrimaryUrl" defaultValue={string(s.heroPrimaryUrl, "/prodavnica")} required /></label><label className="field"><span>Sporedno dugme</span><input name="heroSecondaryLabel" defaultValue={string(s.heroSecondaryLabel, "")} required /></label><label className="field"><span>Sporedni link</span><input name="heroSecondaryUrl" defaultValue={string(s.heroSecondaryUrl, "/kako-funkcionise")} required /></label></div></FormSection><FormSection title="Poverenje i garancija"><label className="field"><span>Naslov garancije</span><input name="guaranteeTitle" defaultValue={string(s.guaranteeTitle, "")} required /></label><label className="field"><span>Tekst garancije</span><textarea name="guaranteeText" defaultValue={string(s.guaranteeText, "")} required /></label><div className="form-grid"><label className="field"><span>Pogodnost 1</span><input name="trustItemOne" defaultValue={string(s.trustItemOne, "")} required /></label><label className="field"><span>Pogodnost 2</span><input name="trustItemTwo" defaultValue={string(s.trustItemTwo, "")} required /></label><label className="field"><span>Pogodnost 3</span><input name="trustItemThree" defaultValue={string(s.trustItemThree, "")} required /></label></div></FormSection><div className="form-submit"><button className="button" type="submit" disabled={busy}>Sačuvaj sadržaj</button><a className="button secondary" href="/" target="_blank" rel="noreferrer">Pogledaj sajt ↗</a></div></form> : null}

          {activeTab === "podesavanja" ? <form className="admin-panel admin-form wide-form" key={JSON.stringify(s)} onSubmit={(event) => void saveSettings(event, "operations")}><div className="panel-heading"><div><h2>Dostava i naplata</h2><p>Pravila važe za obračun korpe, checkout i nalog kupca.</p></div><button className="button small" type="submit" disabled={busy}>Sačuvaj</button></div><FormSection title="Termin i cutoff"><div className="form-grid"><label className="field"><span>Dan dostave</span><select name="deliveryWeekday" defaultValue={number(s.deliveryWeekday, 5)}><option value="1">Ponedeljak</option><option value="2">Utorak</option><option value="3">Sreda</option><option value="4">Četvrtak</option><option value="5">Petak</option><option value="6">Subota</option></select></label><label className="field"><span>Vreme</span><input name="deliveryLocalTime" type="time" defaultValue={string(s.deliveryLocalTime, "08:00")} required /></label><label className="field"><span>Rok za izmenu (sati)</span><input name="cutoffHours" type="number" min="0" defaultValue={number(s.cutoffHours, 24)} required /></label><label className="field"><span>Kapacitet rute (0 = bez limita)</span><input name="routeCapacity" type="number" min="0" defaultValue={number(s.routeCapacity)} /></label></div></FormSection><FormSection title="Zona dostave"><label className="field"><span>Naslov provere</span><input name="serviceAreaTitle" defaultValue={string(s.serviceAreaTitle, "Proverite sledeću dostavu")} required /></label><label className="field"><span>Napomena</span><input name="serviceAreaNote" defaultValue={string(s.serviceAreaNote, "")} required /></label><label className="field"><span>Poštanski brojevi ili prefiksi, odvojeni zarezom</span><input name="servicePostalCodes" defaultValue={Array.isArray(s.servicePostalCodes) ? s.servicePostalCodes.join(", ") : ""} placeholder="11, 21" /></label></FormSection><FormSection title="Trošak dostave i marža"><div className="form-grid"><label className="field"><span>Cena po jednoj dostavi (RSD)</span><input name="deliveryFeeRsd" type="number" min="0" defaultValue={number(s.deliveryFeeMinor) / 100} /></label><label className="field"><span>Besplatna dostava iznad (RSD, 0 = isključeno)</span><input name="freeDeliveryThresholdRsd" type="number" min="0" defaultValue={number(s.freeDeliveryThresholdMinor) / 100} /></label><label className="field"><span>Procenjeni stvarni trošak jedne dostave (RSD)</span><input name="estimatedDeliveryCostRsd" type="number" min="0" defaultValue={number(s.estimatedDeliveryCostMinor) / 100} /></label><label className="field"><span>Payment fee (%)</span><input name="paymentFeePercent" type="number" min="0" max="100" step="0.01" defaultValue={number(s.paymentFeeBps) / 100} /></label></div></FormSection><button className="button" type="submit" disabled={busy}>Sačuvaj operativna pravila</button></form> : null}
          {activeTab === "podesavanja" ? <OperationsPanel integrations={data.integrations} billingMonth={billingMonth} busy={busy} onBillingMonth={setBillingMonth} onRunBilling={() => void runBilling()} onProcess={() => void runIntegrationAction("process")} onRetry={() => void runIntegrationAction("retry_failed")} /> : null}
        </section>}
      </section>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string | number }) { return <article className="admin-panel stat-card"><span>{label}</span><strong>{value}</strong></article>; }
function DataTable({ headers, empty, children }: { headers: string[]; empty: string; children: React.ReactNode }) { const count = Array.isArray(children) ? children.length : children ? 1 : 0; return <section className="admin-panel"><div className="table-wrap"><table><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>{count === 0 ? <p className="admin-empty">{empty}</p> : null}</section>; }
function FormSection({ title, description, children }: { title: string; description?: string; children: React.ReactNode }) { return <section className="form-section"><div><h3>{title}</h3>{description ? <p>{description}</p> : null}</div><div className="form-section-fields">{children}</div></section>; }
function Check({ name, label, checked }: { name: string; label: string; checked: boolean }) { return <label className="checkbox-row"><input type="checkbox" name={name} defaultChecked={checked} /><span>{label}</span></label>; }

function OperationsPanel({ integrations, billingMonth, busy, onBillingMonth, onRunBilling, onProcess, onRetry }: { integrations: Row; billingMonth: string; busy: boolean; onBillingMonth: (value: string) => void; onRunBilling: () => void; onProcess: () => void; onRetry: () => void }) {
  const config = row(integrations.config); const outbox = unwrapList(integrations, ["outbox"]).map(row); const receipts = unwrapList(integrations, ["recentReceipts"]).map(row); const failures = unwrapList(integrations, ["failures"]).map(row);
  const statusCount = (status: string) => number(outbox.find((item) => string(item.status) === status)?.count);
  return <section className="admin-panel admin-form wide-form"><div className="panel-heading"><div><h2>Automatika i integracije</h2><p>Obračun radi odmah; Badi, email i banka ostaju u bezbednom lokalnom režimu dok ne unesemo prave pristupe.</p></div></div><div className="admin-grid-2"><div className="form-section-fields"><h3>Mesečni obračun</h3><p>Generiše po jednu mesečnu fakturu po pretplati, sa nedeljnim ili dvonedeljnim terminima i prenosom kredita.</p><div className="inline-controls"><label className="field"><span>Mesec</span><input type="month" value={billingMonth} onChange={(event) => onBillingMonth(event.target.value)} /></label><button className="button small" type="button" disabled={busy} onClick={onRunBilling}>Pokreni obračun</button></div></div><div className="form-section-fields"><h3>Red za slanje</h3><ul className="list-clean"><li className="summary-row"><span>Na čekanju</span><strong>{statusCount("pending")}</strong></li><li className="summary-row"><span>Poslato / obrađeno</span><strong>{statusCount("sent")}</strong></li><li className="summary-row"><span>Neuspešno</span><strong>{statusCount("failed")}</strong></li></ul><div className="button-row"><button className="button small" type="button" disabled={busy} onClick={onProcess}>Obradi sada</button><button className="button secondary small" type="button" disabled={busy || !failures.length} onClick={onRetry}>Ponovi neuspešne</button></div></div></div><div className="admin-grid-2"><div><h3>Režimi</h3><ul className="list-clean"><li className="summary-row"><span>Naplata</span><strong>{string(row(config.payment).mode)}</strong></li><li className="summary-row"><span>Fiskalizacija</span><strong>{string(row(config.fiscalization).mode)}</strong></li><li className="summary-row"><span>Email</span><strong>{string(row(config.email).mode)}</strong></li></ul></div><div><h3>Poslednji računi</h3>{receipts.length ? <ul className="list-clean">{receipts.slice(0, 5).map((receipt) => <li className="summary-row" key={idOf(receipt)}><span>{string(receipt.order_number)}<small> · {string(receipt.invoice_number, string(receipt.last_error_code, "bez broja"))}</small></span><strong>{statusLabel(string(receipt.status))}</strong></li>)}</ul> : <p className="admin-empty">Još nema obrađenih fiskalnih računa.</p>}</div></div>{failures.length ? <div><h3>Potrebna pažnja</h3><ul className="list-clean">{failures.slice(0, 5).map((failure) => <li className="summary-row" key={idOf(failure)}><span>{string(failure.topic)}<small> · {string(failure.last_error_message)}</small></span><strong>{number(failure.attempts)}×</strong></li>)}</ul></div> : null}</section>;
}

function ProductForm({ product, busy, onSubmit, onCancel }: { product: Product | null; busy: boolean; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onCancel: () => void }) {
  return <form className="admin-editor admin-form" key={product?.id ?? "new"} onSubmit={onSubmit}><div className="panel-heading"><div><h2>{product ? `Izmeni: ${product.name}` : "Novi proizvod"}</h2><p>Sva polja kasnije možete menjati.</p></div><button className="text-button" type="button" onClick={onCancel}>Zatvori ×</button></div><div className="form-grid"><label className="field"><span>Naziv</span><input name="name" defaultValue={product?.name ?? ""} required /></label><label className="field"><span>URL slug</span><input name="slug" defaultValue={product?.slug ?? ""} pattern="[a-z0-9-]+" required /></label><label className="field"><span>Kategorija</span><input name="category" defaultValue={product?.category ?? "Mleko"} required /></label><label className="field"><span>Pakovanje</span><input name="unitLabel" defaultValue={product?.unit ?? "1 L"} required /></label><label className="field"><span>Jednokratna cena (RSD)</span><input name="priceRsd" type="number" min="0" defaultValue={product?.priceRsd ?? 0} required /></label><label className="field"><span>Cena redovne dostave (RSD)</span><input name="subscriptionPriceRsd" type="number" min="0" defaultValue={product?.subscriptionPriceRsd ?? 0} /></label><label className="field"><span>Nabavna/proizvodna cena (RSD)</span><input name="costRsd" type="number" min="0" defaultValue={product?.costRsd ?? 0} /></label><label className="field"><span>Ambalaža po komadu (RSD)</span><input name="packagingCostRsd" type="number" min="0" defaultValue={product?.packagingCostRsd ?? 0} /></label><label className="field"><span>Precrtana cena (RSD)</span><input name="compareAtPriceRsd" type="number" min="0" defaultValue={product?.compareAtPriceRsd ?? ""} /></label><label className="field"><span>Redosled</span><input name="sortOrder" type="number" min="0" defaultValue={product?.sortOrder ?? 0} /></label><label className="field"><span>Badi SKU</span><input name="badiSku" type="number" min="1" step="1" defaultValue={product?.badiSku ?? ""} placeholder="Unosi se pre Badi aktivacije" /></label></div><label className="field"><span>Kratak opis</span><input name="shortDescription" defaultValue={product?.shortDescription ?? ""} /></label><label className="field"><span>Pun opis</span><textarea name="description" defaultValue={product?.description ?? ""} /></label><div className="form-grid"><label className="field"><span>Putanja fotografije</span><input name="imageUrl" defaultValue={product?.imageUrl ?? ""} placeholder="/images/proizvod.jpg" /></label><label className="field"><span>Alt opis fotografije</span><input name="imageAlt" defaultValue={product?.imageAlt ?? ""} /></label><label className="field"><span>Bedž</span><input name="badge" defaultValue={product?.badge ?? ""} placeholder="Najčešći izbor" /></label><label className="field"><span>Poreklo</span><input name="origin" defaultValue={product?.origin ?? ""} /></label><label className="field"><span>SEO naslov</span><input name="seoTitle" defaultValue={product?.seoTitle ?? ""} maxLength={70} /></label><label className="field"><span>SEO opis</span><input name="seoDescription" defaultValue={product?.seoDescription ?? ""} maxLength={170} /></label></div><div className="check-grid"><Check name="isActive" label="Objavljen" checked={product?.available ?? true} /><Check name="isFeatured" label="Izdvojen na početnoj" checked={product?.isFeatured ?? false} /><Check name="allowSubscription" label="Dozvoli redovnu dostavu" checked={product?.allowSubscription ?? true} /><Check name="isDemo" label="Označi kao DEMO" checked={product?.isDemo ?? false} /></div><div className="button-row"><button className="button" type="submit" disabled={busy}>{busy ? "Čuvamo…" : "Sačuvaj proizvod"}</button><button className="button secondary" type="button" onClick={onCancel}>Odustani</button></div></form>;
}

function OrderRow({ order, busy, onSave }: { order: Row; busy: boolean; onSave: (id: string, payment: string, fulfillment: string) => void }) {
  const [payment, setPayment] = useState(string(order.payment_status, "pending")); const [fulfillment, setFulfillment] = useState(string(order.fulfillment_status, "planned"));
  return <tr><td><strong>{string(order.order_number)}</strong><br /><small>{formatDate(string(order.created_at, ""))}</small></td><td>{string(order.full_name)}<br /><small>{string(order.email)}</small></td><td>{formatDate(string(order.delivery_date, ""))}</td><td>{formatMoney(number(order.total_minor) / 100)}</td><td><select value={payment} onChange={(e) => setPayment(e.target.value)}><option value="pending">Na čekanju</option><option value="paid">Plaćeno</option><option value="failed">Neuspešno</option><option value="refunded">Refundirano</option></select></td><td><span className={`status-pill ${string(order.fiscal_status) === "issued" ? "active" : ""}`}>{statusLabel(string(order.fiscal_status, payment === "paid" ? "pending" : "nije dospeo"))}</span>{order.invoice_number ? <><br /><small>{string(order.invoice_number)}</small></> : null}</td><td><select value={fulfillment} onChange={(e) => setFulfillment(e.target.value)}><option value="planned">Planirano</option><option value="locked">Zaključano</option><option value="delivered">Isporučeno</option><option value="cancelled">Otkazano</option></select></td><td><button className="button secondary small" type="button" disabled={busy} onClick={() => onSave(idOf(order), payment, fulfillment)}>Sačuvaj</button></td></tr>;
}
